  "implementation": "def solve(case):
    sentence_vectors = case['sentence_vectors']
    query_vector = case['query_vector']
    context_weight = case['context_weight']
    n = len(sentence_vectors)
    if n == 0:
        return {'ranking': [], 'scores': []}
    import math
    def cosine_sim(vec, q):
        dot = sum(a*b for a,b in zip(vec, q))
        nv = math.sqrt(sum(a*a for a in vec))
        nq = math.sqrt(sum(b*b for b in q))
        if nv == 0 or nq == 0:
            return 0.0
        return dot / (nv * nq)
    sims = [cosine_sim(sv, query_vector) for sv in sentence_vectors]
    navgs = []
    for i in range(n):
        nei = []
        if i > 0:
            nei.append(sims[i-1])
        if i < n-1:
            nei.append(sims[i+1])
        if nei:
            navgs.append(sum(nei) / len(nei))
        else:
            navgs.append(0.0)
    cw = context_weight
    finals = [round((1-cw)*sims[i] + cw*navgs[i], 6) for i in range(n)]
    ranking = sorted(range(n), key=lambda i: (-finals[i], i))
    return {'ranking': ranking, 'scores': finals}"
